        // If y is not the direct right child of z, replace y with its own right child first
        if PARENT(T, y) != z:
            TRANSPLANT(T, y, y.right)
            y.right = z.right

        // Replace z with y
        TRANSPLANT(T, z, y)

        y.left = z.left

    // Find predecessor of z
    pred = TREE-PREDECESSOR(T, z)

    // If predecessor exists, skip z so pred now points to z.succ
    if pred != NIL:
        pred.succ = z.succ
